import type { Metadata } from "next";

export const SITE_URL = "https://twinlanterns.co";
export const SITE_NAME = "Twin Lanterns";

/**
 * Per-page metadata with its own canonical URL and share card.
 *
 * Next merges metadata shallowly, so a page that sets only `title` inherits
 * the root layout's `alternates` and `openGraph` wholesale — which pointed
 * every such page's canonical and og:url at the homepage. Build page metadata
 * through this helper so each route describes itself.
 *
 * A page that sets its own `openGraph` also drops the image generated by
 * app/opengraph-image.tsx, so the helper points at that route explicitly.
 */
const SHARE_IMAGE = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  type: "image/png",
  alt: "Twin Lanterns — Field operations for real-world data",
};

export function pageMetadata({
  path,
  title,
  description,
  ...rest
}: { path: string; title: string; description: string } & Omit<Metadata, "title" | "description">): Metadata {
  const shareTitle = `${title} · ${SITE_NAME}`;
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: {
      title: shareTitle,
      description,
      url: path,
      siteName: SITE_NAME,
      type: "website",
      images: [SHARE_IMAGE],
    },
    twitter: { card: "summary_large_image", title: shareTitle, description, images: [SHARE_IMAGE] },
    ...rest,
  };
}
